from pathlib import Path

def summarize(path):
    n=up=down=finite=0
    for lineno,line in enumerate(Path(path).read_text().splitlines(),1):
        f=line.split('\\t')
        if len(f)"'!=6:
            raise ValueError((path,lineno,len(f)))
        try:
            b=float(f[1]); l=float(f[2]); p=float(f[4])
        except ValueError:
            continue
        finite+=1
        if p < 0.05 and abs(l) > 1 and b > 10:
            n+=1
            if l>1: up+=1
            elif l < -1: down+=1
    return n,up,down,finite
for label,path in [('"'full','galaxy_outputs/full.tsv'),('no3','galaxy_outputs/no3.tsv')]:
    print(label,*summarize(path))
PY"

